# The SSD-MobileNetV1 ONNX export from the (Apache-2.0 / MIT) ONNX Model Zoo, mirrored
# on the Hugging Face Hub. ~28 MB; downloaded once via huggingface_hub and cached like
# any HF model weights (~/.cache/huggingface), the same pattern upload_classify.py uses.
_MODEL_REPO = "onnxmodelzoo/ssd_mobilenet_v1_12"
_MODEL_FILE = "ssd_mobilenet_v1_12.onnx"

# Only detections at least this confident are shown - the model's own NMS already
# trims low-quality proposals, but this keeps the noise floor off the UI.
_SCORE_THRESHOLD = 0.3
_MAX_BOXES = 20  # a hard cap so a busy scene can't flood the overlay

# An upload larger than this is downscaled before inference (longest edge, pixels) -
# the model accepts any size, but a multi-megapixel phone photo would otherwise cost
# much more CPU time than the demo needs to spend per request.
_MAX_INFERENCE_SIDE = 640

# Server-side content-type allowlist for uploads (ADR-0024): the detector only ever
# needs a still image, and this is a public demo, so reject anything else before it's
# decoded rather than trusting the client-supplied Content-Type alone for identity.
_ALLOWED_UPLOAD_TYPES = {"image/jpeg", "image/png", "image/webp"}

_session = None  # lazily-loaded onnxruntime.InferenceSession, cached across calls
_input_name = None  # the session's input tensor name, cached alongside it


def _load_session():
    """Download (once, cached) and load the ONNX model. Lazy so importing this
    module -- and indah's own test suite -- never requires onnxruntime installed."""
    global _session, _input_name
    if _session is None:
        from huggingface_hub import hf_hub_download
        from onnxruntime import InferenceSession

        path = hf_hub_download(repo_id=_MODEL_REPO, filename=_MODEL_FILE)
        _session = InferenceSession(path, providers=["CPUExecutionProvider"])
        _input_name = _session.get_inputs()[0].name
    return _session, _input_name


def _predict(data: bytes):
    """Decode ``data`` with Pillow and run one onnxruntime inference.

    Returns the model's raw ``(boxes, classes, scores, num_detections)`` for one
    image: ``boxes`` are ``(ymin, xmin, ymax, xmax)`` fractions of the image,
    already sorted most-confident first by the model's own NMS.
    """
    import io

    import numpy as np
    from PIL import Image as PILImage

    image = PILImage.open(io.BytesIO(data)).convert("RGB")
    if max(image.size) > _MAX_INFERENCE_SIDE:
        scale = _MAX_INFERENCE_SIDE / max(image.size)
        size = (max(1, round(image.width * scale)), max(1, round(image.height * scale)))
        image = image.resize(size)
    batch = np.asarray(image, dtype=np.uint8)[np.newaxis, ...]  # NHWC uint8, any size

    session, input_name = _load_session()
    boxes, classes, scores, num_detections = session.run(None, {input_name: batch})
    return boxes[0], classes[0], scores[0], int(num_detections[0])


def detect(data: bytes) -> list[dict]:
    """The detected objects in an image's raw bytes, run live on CPU.

    Coordinates are fractions of the image ([0, 1]), the convention
    ``ImageOverlay`` expects. A real GPU model, or a bigger/more accurate CPU one,
    would drop in behind this same signature with the rest of the app unchanged.
    """
    boxes, classes, scores, num_detections = _predict(data)
    detections = []
    for i in range(min(num_detections, len(scores))):
        score = float(scores[i])
        if score < _SCORE_THRESHOLD:
            continue
        ymin, xmin, ymax, xmax = (float(v) for v in boxes[i])
        xmin, ymin = max(0.0, xmin), max(0.0, ymin)
        xmax, ymax = min(1.0, xmax), min(1.0, ymax)
        if xmax <= xmin or ymax <= ymin:
            continue  # a degenerate box the model itself wouldn't draw
        detections.append(
            {
                "x": round(xmin, 4),
                "y": round(ymin, 4),
                "w": round(xmax - xmin, 4),
                "h": round(ymax - ymin, 4),
                "label": COCO_LABELS.get(int(classes[i]), "object"),
                "score": round(score, 2),
            }
        )
        if len(detections) >= _MAX_BOXES:
            break
    return detections


def _data_uri(file: UploadedFile) -> str:
    """The uploaded image bytes as a data: URI, so the shell can show it back."""
    mime = file.content_type or "image/png"
    return f"data:{mime};base64," + base64.b64encode(file.data).decode("ascii")


# Five sample photos with several detectable objects each, so a first-time visitor
# sees the model work before trying their own (and possibly stumping it on a single
# awkward subject). All CC0 (public domain), from Wikimedia Commons: Man_riding_
# bicycle_(Unsplash).jpg (Clem Onojeghuo), Kippenheim_vehicles_logistics_giant_
# parking_lot_8.jpg (Syced), Laptop_in_the_living_room_(Unsplash).jpg (Oliur Rahman),
# After_Work_Drink_(Unsplash).jpg (Guillermo Nolasco), Suitcase_loading_in_Ben_
# Gurion_airport.jpg. Embedded here, not fetched at runtime, for the same reason as
# COCO_LABELS above: the Colab notebook only gets this module's own source text.
_SAMPLES: dict[str, tuple[str, str]] = {
    "cyclist": (
        "Cyclist",
        "",
    ),
    "parking": (
        "Parking lot",
        "",
    ),
    "living-room": (
        "Living room",
        "",
    ),
    "drinks": (
        "Drinks",
        "",
    ),
    "luggage": (
        "Luggage",
        "",
    ),
}


def _status_line(boxes: list, source: str) -> str:
    noun = "object" if len(boxes) == 1 else "objects"
    return f"Detected **{len(boxes)}** {noun} in {source}. Hover a box to read its label."


def build_session() -> Session:
    """A fresh per-viewer graph: pick (or upload) an image, detect objects, show boxes."""
    preview: Signal[str] = Signal("")
    detections: Signal[list] = Signal([])
    status: Signal[str] = Signal("")
    busy: Signal[bool] = Signal(False)

    async def _run(data: bytes, preview_uri: str, source: str) -> None:
        busy.set(True)
        status.set("")
        detections.set([])
        preview.set(preview_uri)
        # onnxruntime inference is synchronous CPU work; run it off the event loop
        # so it never blocks the UI, the same guarantee upload_classify.py's
        # asyncio.to_thread call gives its (also synchronous, thread-run) classify.
        boxes = await asyncio.to_thread(detect, data)
        detections.set(boxes)
        status.set(_status_line(boxes, source))
        busy.set(False)

    async def on_upload(file: UploadedFile) -> None:
        if file.content_type not in _ALLOWED_UPLOAD_TYPES:
            status.set(
                f"_Unsupported file type '{file.content_type}' - "
                "upload a JPEG, PNG, or WebP image._"
            )
            return
        await _run(file.data, _data_uri(file), "the uploaded image")

    async def on_sample(slug: str) -> None:
        if busy.value:
            return
        label, b64 = _SAMPLES[slug]
        preview_uri = f"data:image/jpeg;base64,{b64}"
        await _run(base64.b64decode(b64), preview_uri, f"'{label}'")

    sample_buttons = Row(
        children=[
            Button(label, on_click=(lambda s=slug: on_sample(s)), variant="ghost")
            for slug, (label, _b64) in _SAMPLES.items()
        ],
        gap="0.5rem",
    )

    session = Session(
        Column(
            children=[
                Text(
                    "# Object detection\n\n"
                    "Click a sample photo, or upload your own, and a real "
                    "SSD-MobileNetV1 model boxes what it finds - live, on CPU. Hover "
                    "a box for its label - scroll to zoom into a small detection, "
                    "drag to pan once zoomed. Each tab is its own session, so your "
                    "upload and results stay private to it.",
                    markdown=True,
                ),
                Card(
                    title="Input",
                    children=[
                        Text("Try a sample:"),
                        sample_buttons,
                        Upload(on_upload, accept="image/*", label="Or upload your own"),
                        Spinner(active=busy, label="Detecting..."),
                    ],
                ),
                Card(
                    title="Result",
                    children=[
                        ImageOverlay(
                            preview,
                            boxes=detections,
                            label_mode="hover",
                            alt="the detected image",
                        ),
                        Text(lambda: status.value or "_No detections yet._", markdown=True),
                    ],
                ),
            ]
        )
    )

    # A5 UX (docs/DEMOS-DOCS-ROUND2.md): run real detection on the first sample right
    # away, so a visitor sees the model work with no click required - Upload stays the
    # secondary "or try your own" path. Signals are read fresh at snapshot time
    # (Component.to_json), so setting them here, before the session's first render,
    # is enough - no synthetic event needed.
    _first_slug, (first_label, first_b64) = next(iter(_SAMPLES.items()))
    first_bytes = base64.b64decode(first_b64)
    preview.set(f"data:image/jpeg;base64,{first_b64}")
    boxes = detect(first_bytes)
    detections.set(boxes)
    status.set(_status_line(boxes, f"'{first_label}'"))

    return session


# Module-level ASGI app for hosting. A lower cap than the framework's 25 MB default
# (ADR-0024): sample photos are small and a detector has no use for a large upload.
app = create_app(session_factory=build_session, max_upload_mb=4)


if __name__ == "__main__":
    indah.launch(app)
